def apply_conflict_mutation(op: str, existing_edge: dict | None, new_fact: dict, now_ts: int) -> list[dict]:
    if op == "NOOP":
        return []
    if op == "DELETE" and existing_edge:
        existing_edge["t_invalid"] = now_ts
        return [existing_edge]
    if op == "UPDATE" and existing_edge:
        existing_edge["t_invalid"] = now_ts
        return [existing_edge, {**new_fact, "t_valid": now_ts, "t_invalid": None}]
    return [{**new_fact, "t_valid": now_ts, "t_invalid": None}]  # ADD

import math

def ebbinghaus_retention(dt_hours: float, stability: float, importance: float, decay_const: float = 0.05) -> float:
    denom = max(stability * importance, 1e-6)
    return math.exp(-(decay_const * dt_hours) / denom)

def execute_gdpr_crypto_shred(namespace_id: str, redis_client, kms_client, purge_queue) -> dict:
    redis_client.delete(f"wm:{namespace_id}")
    redis_client.set(f"tombstone:{namespace_id}", "1", ex=86400)
    purge_queue.enqueue({"namespace_id": namespace_id, "targets": ["qdrant", "neo4j"]})
    kms_client.schedule_key_destruction(key_alias=f"dek/{namespace_id}")
    return {"status": "CRYPTO_SHREDDED", "namespace_id": namespace_id}
